//@ run-pass
//@ requires: madaros
//@ expect-stdout: TUPLE_ARR_HASH_LONG_NAME_COLLISION PASS
//
// Copilot review (PR #2516) finding #1 on the second review round:
// fo_name_hash/fo_name_hash2 (self-hosted/ir/lower.sio) used to cap their
// rolling hash at the first 64 bytes of the name, even though `Name.buf` is
// `[i8; 384]` and the parser accepts identifiers that long. Two function
// names sharing a 64-byte-plus common prefix but differing only AFTER byte
// 64 therefore hashed identically in BOTH LOWER_FN_TUPLE_ARR_HASH and
// LOWER_FN_TUPLE_ARR_HASH2, so `lower_fn_tuple_f64_array_mask` could return
// one function's array-slot mask for a DIFFERENT function sharing that
// truncated prefix -- exactly the bits-as-i64 (or, here, the mirror-image
// bits-as-f64) corruption this whole side table exists to prevent, just
// reached via a long-name collision instead of a short-name one.
//
// The two names below share a 64-byte prefix and differ only in their last
// two characters ("aa" vs "bb"). `..aa` returns a tuple of two f64 arrays
// (mask = 3, both slots arrays). `..bb` returns a tuple whose slot 0 is a
// plain [i64; 2] array and whose slot 1 is an [f64; 2] array (mask = 2, only
// slot 1 an array). If the hash were still truncated at 64 bytes, both names
// would collide in the table and `..bb`'s lookup could pick up `..aa`'s
// mask (3) instead of its own (2), wrongly marking `..bb`'s INTEGER slot 0
// as an f64 array too -- so reading its plain i64 elements would misread
// the raw bits as f64 (the mirror image of the original kinetics bug, same
// root cause: a stale/wrong mask from an unrelated function).
fn nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkaa() -> ([f64; 2], [f64; 2]) with Mut, Panic {
    var a: [f64; 2] = [0.0; 2]
    var b: [f64; 2] = [0.0; 2]
    a[0] = 1.5
    b[0] = 0.25
    (a, b)
}

fn nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkbb() -> ([i64; 2], [f64; 2]) with Mut, Panic {
    var ints: [i64; 2] = [0; 2]
    var floats: [f64; 2] = [0.0; 2]
    ints[0] = 7
    floats[0] = 0.25
    (ints, floats)
}

fn main() -> i32 with IO, Mut, Panic {
    let (oa, ob) = nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkaa()
    let s0: f64 = oa[0] * 2.0
    let s1: f64 = 2.0 * ob[0]

    let (ib, fb) = nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkbb()
    let v = ib[0] * 2
    let fv: f64 = fb[0] * 2.0

    if s0 == 3.0 && s1 == 0.5 && v == 14 && fv == 0.5 {
        println("TUPLE_ARR_HASH_LONG_NAME_COLLISION PASS")
        return 0
    }
    1
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: TUPLE_F64_ARRAY_METHOD_CALL_DESTRUCTURE PASS
//
// Copilot review (PR #2516) finding #5, ExprMethodCall half:
// `let (a, b) = obj.pair()` where `pair` is an impl method (not a free fn)
// returning `([f64; N], [f64; N])`. expr_result_tuple_arr_mask_ref only
// handled ExprKind::ExprCall, so a method-call tuple producer's destructured
// arrays never got f64-array-slot metadata and `a[0] * 2.0` misread the f64
// bit pattern as an i64.
struct Pairer {
    scale: f64,
}

impl Pairer {
    fn pair(self) -> ([f64; 2], [f64; 2]) with Mut, Panic {
        var a: [f64; 2] = [0.0; 2]
        var b: [f64; 2] = [0.0; 2]
        a[0] = 1.5 * self.scale
        a[1] = 0.25
        b[0] = 4.5
        (a, b)
    }
}

fn main() -> i32 with IO, Mut, Panic {
    let p = Pairer { scale: 1.0 }
    let (a, b) = p.pair()
    let s0: f64 = a[0] * 2.0
    let s1: f64 = 2.0 * b[0]
    var acc: f64 = 0.0
    var j: i64 = 0
    while j < 2 {
        acc = acc + 0.5 * a[j]
        j = j + 1
    }
    if s0 == 3.0 && s1 == 9.0 && acc == 0.875 {
        println("TUPLE_F64_ARRAY_METHOD_CALL_DESTRUCTURE PASS")
        return 0
    }
    1
}

//@ run-pass
//@ expect-stdout: MATH_ATAN_REDUCTION_OK
// NOTE, and deliberately not an annotation: Madaros refuses the bare `atan`
// with E221 -- its backend has no builtin id
// for tan/atan/tanh/asin/acos, so the call would compile and then die on an
// illegal instruction. That refusal is correct, and it makes this file a
// lean_single test -- which is what it always was: the bug it guards lived in
// lean_single's __native_atan_f64, and CI's suite compiles with souc-stage2,
// which IS lean_single. No engine annotation is written here, and mentioning the
// literal marker in prose is itself a trap: run_sio_test_suite_v2.sh matches the
// requires marker ANYWHERE on a line, comment or not, so a sentence naming it
// becomes one. This file failed CI that way once. The accepted values are
// gpu, llvm and madaros; anything else fails hard, which is the defect #2155
// fixed.

// atan's argument reduction used `base > 0.0` as the proxy for "the reciprocal
// branch fired". It is not one: the SECOND reduction, t = (t-1)/(t+1), also
// raises base — to pi/4. So a value that took the second reduction WITHOUT the
// first got the minus branch, and atan(0.5) returned 1.107149, which is atan(2).
//
// The endpoints hid it for as long as it lived. atan(1) is pi/4 either way;
// atan(2) fires BOTH reductions, and the two sign errors cancel. asin and acos
// are built on atan, so asin(0.5) returned acos(0.5) and acos(0.5) returned
// asin(0.5) — a swap at one point that is not a swap anywhere else.
//
// The two identities carry different signs and the branch decides which:
//   |x| > 1 : atan(x) = pi/2 - atan(1/x)          -> base - a
//   reduce  : atan(t) = pi/4 + atan((t-1)/(t+1))  -> base + a
//
// Points chosen to hit each combination of the two reductions:
//   0.2  neither      1.0  second only, a = 0
//   0.5  second only  2.0  both            5.0  first only
// and one negative, because the sign is applied after both.

// 1e-6, not 1e-9, and the number is a property of the implementation rather
// than slack. The series runs to t^13 and the reduction leaves |t| <= 0.4142,
// so the first dropped term is about 0.4142^15 / 15 ~= 1.2e-7. A 1e-9 bound
// would fail on correct output, which is worse than useless in a regression
// test: it would be red for a reason unrelated to the defect it guards.
fn near(a: f64, b: f64) -> bool {
    let d = a - b
    if d < 0.0 { return 0.0 - d < 1.0e-6 }
    return d < 1.0e-6
}

fn main() with IO, Mut, Div {
    let ok = near(atan(0.2), 0.19739555984988078)
        && near(atan(0.5), 0.4636476090008061)
        && near(atan(1.0), 0.7853981633974483)
        && near(atan(2.0), 1.1071487177940904)
        && near(atan(5.0), 1.3734007669450159)
        && near(atan(0.0 - 0.5), 0.0 - 0.4636476090008061)
        && near(asin(0.5), 0.5235987755982989)
        && near(asin(0.8), 0.9272952180016122)
        && near(acos(0.5), 1.0471975511965979)
        && near(acos(0.8), 0.6435011087932844)
    if ok {
        print("MATH_ATAN_REDUCTION_OK\n")
    } else {
        print("MATH_ATAN_REDUCTION_FAIL\n")
        print("atan(0.2)="); print_f64(atan(0.2)); print(" want 0.197396\n")
        print("atan(0.5)="); print_f64(atan(0.5)); print(" want 0.463648\n")
        print("atan(1.0)="); print_f64(atan(1.0)); print(" want 0.785398\n")
        print("atan(2.0)="); print_f64(atan(2.0)); print(" want 1.107149\n")
        print("atan(5.0)="); print_f64(atan(5.0)); print(" want 1.373401\n")
        print("atan(-0.5)="); print_f64(atan(0.0 - 0.5)); print(" want -0.463648\n")
        print("asin(0.5)="); print_f64(asin(0.5)); print(" want 0.523599\n")
        print("asin(0.8)="); print_f64(asin(0.8)); print(" want 0.927295\n")
        print("acos(0.5)="); print_f64(acos(0.5)); print(" want 1.047198\n")
        print("acos(0.8)="); print_f64(acos(0.8)); print(" want 0.643501\n")
    }
}

//@ run-pass
// tests/run-pass/mercyful_pontryagin_control.sio
//
// Mercyful Learning x continuous optimal control (Pontryagin rung), Sounio
// native. Closed-form optimal-control structure of the suffering ODE
//
//   dd/dt = -a*u*d,   s(t) = c*d(t) + tau*u(t),   u in [0, u_max]
//
// with anti-Goodhart target d(T) = d_T and Mercyful objective
// J = ∫ s dt + mu * max s. Verifies natively, from the same closed forms as
// the Python twin:
//   K1 baseline bang numbers (V, t_B, m_B, I_B)
//   K4 frontier points I*(m), T*(m) at m = 2.0 (hybrid iso->bang) and
//      m = 1.5 (pure iso-suffering boundary arc)
//   K5 smooth crossover: curvature of I* at the bang peak = 1/(2 a tau u_max^2)
//      and the first-order exchange law m*(mu) = m_B - mu*a*tau*u_max^2
//   K6 budgetary necessity peak_min(L0) = (T*)^-1(L0) via bisection
//
// Spec: docs/research/mercyful_pontryagin_control_spec_2026-07-26.md
// Gate: scripts/ci/mercyful_pontryagin_control_gate.sh
// Python twin (K1..K9): scripts/research/mercyful_pontryagin_control_contract.py
//
// Clinical warning: synthetic ODE, synthetic suffering values, normalized
// units. This is not medical guidance and carries no clinical claim.

extern "C" {
    fn log(x: f64) -> f64;
    fn exp(x: f64) -> f64;
}

// Synthetic instance (normalized; spec section 4)
let D0: f64 = 1.0
let DT: f64 = 0.05
let A: f64 = 1.0
let UMAX: f64 = 2.0
let C: f64 = 1.0
let TAU: f64 = 1.0

// (I*(m), T*(m)): min suffering integral and min time under peak cap s <= m.
fn closed_form_i(m: f64) -> f64 {
    let d_join = (m - TAU * UMAX) / C
    if d_join <= DT {
        let t_iso = (TAU / (A * m)) * log(((m - C * DT) / (C * DT)) * ((C * D0) / (m - C * D0)))
        return m * t_iso
    }
    let k = (m - C * D0) / (C * D0)
    let t_iso = (TAU / (A * m)) * log((TAU * UMAX / (C * d_join)) / k)
    let i_bang = (C / (A * UMAX)) * (d_join - DT) + (TAU / A) * log(d_join / DT)
    m * t_iso + i_bang
}

fn closed_form_t(m: f64) -> f64 {
    let d_join = (m - TAU * UMAX) / C
    if d_join <= DT {
        return (TAU / (A * m)) * log(((m - C * DT) / (C * DT)) * ((C * D0) / (m - C * D0)))
    }
    let k = (m - C * D0) / (C * D0)
    let t_iso = (TAU / (A * m)) * log((TAU * UMAX / (C * d_join)) / k)
    let t_bang = (1.0 / (A * UMAX)) * log(d_join / DT)
    t_iso + t_bang
}

// Budgetary necessity: minimal attainable peak under horizon budget L0.
// Returns -1.0 when infeasible (L0 < t_B).
fn peak_min(l0: f64) -> f64 with Mut {
    let t_b = closed_form_t(3.0)
    if l0 < t_b { return 0.0 - 1.0 }
    var lo = 1.0 + 1e-9
    var hi = 3.0
    var i = 0
    while i < 200 {
        let mid = 0.5 * (lo + hi)
        if closed_form_t(mid) <= l0 { hi = mid } else { lo = mid }
        i = i + 1
    }
    hi
}

// argmin_m I*(m) + mu*m on a grid (K5 exchange law).
fn m_star(mu: f64) -> f64 with Mut {
    var best_m = 3.0
    var best_j = 1e100
    var i = 0
    while i < 6000 {
        let m = 1.0001 + (3.0 - 1.0001) * (i as f64) / 5999.0
        let j = closed_form_i(m) + mu * m
        if j < best_j { best_j = j; best_m = m }
        i = i + 1
    }
    best_m
}

fn fabs_(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    x
}

fn main() -> i32 with IO, Mut {
    var failures = 0

    // K1: baseline bang numbers.
    let v = log(D0 / DT) / A
    let t_b = v / UMAX
    let m_b = C * D0 + TAU * UMAX
    let i_b = (C / (A * UMAX)) * (D0 - DT) + TAU * v
    println(v)
    println(t_b)
    println(m_b)
    println(i_b)
    if fabs_(v - 2.995732) < 1e-6 && fabs_(t_b - 1.497866) < 1e-6
        && m_b == 3.0 && fabs_(i_b - 3.470732) < 1e-6 {
        println("K1_BASELINE PASS")
    } else {
        println("K1_BASELINE FAIL")
        failures = failures + 1
    }

    // K4: frontier closed forms at m = 2.0 (hybrid) and m = 1.5 (pure iso).
    let i20 = closed_form_i(2.0)
    let t20 = closed_form_t(2.0)
    let i15 = closed_form_i(1.5)
    let t15 = closed_form_t(1.5)
    println(i20)
    println(t20)
    println(i15)
    println(t15)
    if fabs_(i20 - 3.663562) < 1e-6 && fabs_(t20 - 1.831781) < 1e-6
        && fabs_(i15 - 4.060443) < 1e-6 && fabs_(t15 - 2.706962) < 1e-6 {
        println("K4_FRONTIER PASS")
    } else {
        println("K4_FRONTIER FAIL")
        failures = failures + 1
    }

    // K5: smooth crossover. Curvature of I* at the bang peak from below is
    // exactly 1/(2*a*tau*u_max^2) = 0.125, and m*(0.001) = m_B - 0.004.
    let eps = 0.01
    let curv = (closed_form_i(m_b - eps) - i_b) / (eps * eps)
    let ms = m_star(0.001)
    println(curv)
    println(ms)
    if fabs_(curv - 0.125) < 0.0025 && fabs_(ms - 2.996) < 0.002 {
        println("K5_SMOOTH_CROSSOVER PASS")
    } else {
        println("K5_SMOOTH_CROSSOVER FAIL")
        failures = failures + 1
    }

    // K6: budgetary necessity via bisection; infeasible below t_B.
    let pm2 = peak_min(2.0)
    let pm3 = peak_min(3.0)
    let pm_tight = peak_min(1.4)
    println(pm2)
    println(pm3)
    if fabs_(pm2 - 1.867628) < 1e-6 && fabs_(pm3 - 1.402552) < 1e-6 && pm_tight < 0.0 {
        println("K6_BUDGETARY_NECESSITY PASS")
    } else {
        println("K6_BUDGETARY_NECESSITY FAIL")
        failures = failures + 1
    }

    if failures == 0 {
        println("MERCYFUL_PONTRYAGIN_PASS")
        return 0
    }
    println("MERCYFUL_PONTRYAGIN_FAIL")
    1
}

//@ run-pass
//@ expect-stdout-contains: PASS multi_drug_aggregate
// tests/run-pass/multi_drug_aggregate_test.sio
//
// End-to-end gate for darwin_pbpk::aggregate_confidence.
//
// Inputs (per the dissertation's three-drug study):
//   rapamycin     c = 0.612
//   haloperidol   c = 0.587
//   DES sirolimus c = 0.503
//
// Expected (computed by hand, verified by stdout-diff against
// tests/golden/multi_drug_conf/aggregator_outputs.txt):
//   worst_case    = 0.503
//   rss           = 1 - sqrt(0.388² + 0.413² + 0.497²)
//                 = 1 - sqrt(0.150544 + 0.170569 + 0.247009)
//                 = 1 - sqrt(0.568122)  ≈ 1 - 0.753738  ≈ 0.246262
//   cov_weighted (ρ = I) = rss  (bit-identical via the same sqrt path)

use darwin_pbpk::aggregate_confidence::*

fn approx_eq(a: f64, b: f64, tol: f64) -> bool with Mut, Div, Panic {
    var d: f64 = a - b
    if d < 0.0 { d = 0.0 - d }
    d < tol
}

fn build_three_drug_input() -> MultiDrugInput with Mut, Div, Panic {
    var inp = multi_drug_input_zero()
    inp.n_drugs = 3
    inp.confidence[0] = 0.612    // rapamycin
    inp.confidence[1] = 0.587    // haloperidol
    inp.confidence[2] = 0.503    // DES sirolimus
    inp.rho = rho_identity()
    inp
}

fn fail(tag: string) with IO, Mut, Panic, Div {
    print("FAIL multi_drug_aggregate: ")
    println(tag)
}

fn main() with IO, Mut, Panic, Div {
    let inp = build_three_drug_input()

    // ---- Rule 1: worst_case ----
    let wc = aggregate_worst_case(inp)
    if !approx_eq(wc, 0.503, 1e-12) {
        fail("worst_case_value")
        return
    }

    // ---- Rule 2: rss ----
    let rss = aggregate_rss(inp)
    if !approx_eq(rss, 0.246262, 1e-4) {
        fail("rss_value")
        return
    }

    // ---- Rule 3: cov_weighted with rho = I ----
    let cw = aggregate_cov_weighted(inp)
    if !approx_eq(cw, rss, 1e-12) {
        fail("cov_weighted_eq_rss_when_rho_identity")
        return
    }

    // ---- --min-conf gate behaviour ----
    // At min_conf = 0.5: worst_case ADMITS (0.503 >= 0.5), rss REFUSES.
    let v_wc_strict = aggregate_evaluate(inp, 0, 0.5)
    if !v_wc_strict.admitted {
        fail("worst_case_strict_should_admit")
        return
    }
    let v_rss_strict = aggregate_evaluate(inp, 1, 0.5)
    if v_rss_strict.admitted {
        fail("rss_strict_should_refuse")
        return
    }

    // At min_conf = 0.2: all rules ADMIT.
    let v_wc_loose = aggregate_evaluate(inp, 0, 0.2)
    if !v_wc_loose.admitted {
        fail("worst_case_loose_should_admit")
        return
    }
    let v_rss_loose = aggregate_evaluate(inp, 1, 0.2)
    if !v_rss_loose.admitted {
        fail("rss_loose_should_admit")
        return
    }
    let v_cw_loose = aggregate_evaluate(inp, 2, 0.2)
    if !v_cw_loose.admitted {
        fail("cov_weighted_loose_should_admit")
        return
    }

    // ---- Weakest-drug identification ----
    if v_wc_strict.weakest != 2 {
        fail("weakest_idx_should_be_2")
        return
    }
    if !approx_eq(v_wc_strict.weakest_c, 0.503, 1e-12) {
        fail("weakest_c_should_be_0.503")
        return
    }

    // ---- Empty-input edge case (n_drugs=0 → aggregate=1.0, ADMIT) ----
    let empty = multi_drug_input_zero()
    if !approx_eq(aggregate_worst_case(empty), 1.0, 1e-12) {
        fail("empty_worst_case_should_be_1")
        return
    }
    if !approx_eq(aggregate_rss(empty), 1.0, 1e-12) {
        fail("empty_rss_should_be_1")
        return
    }

    // ---- Deterministic stdout snapshot — keeps the gate's golden honest ----
    aggregate_print_verdict(v_wc_strict)
    aggregate_print_verdict(v_rss_strict)
    aggregate_print_verdict(v_cw_loose)

    println("PASS multi_drug_aggregate")
}

